// Doxygen-style frame around the mdBook pages (see doxygen.css): title area
// with logo, project number and brief; tab bar with the search box; the
// breadcrumb and "generated by" bar at the bottom.
(function () {
  "use strict";
  var root = typeof path_to_root === "string" ? path_to_root : "";
  // the version in the title and footer: bumped with Cargo.toml (release checklist)
  var version = "0.2.7";
  var tabs = [
    { label: "Main Page", href: "index.html", match: /\/TeamCraft\/(index\.html)?$|^\/(index\.html)?$/ },
    { label: "User Guide", href: "guide/getting-started.html", match: /\/guide\// },
    { label: "Administration", href: "admin/configuration.html", match: /\/admin\// },
    { label: "Reference", href: "reference/formats.html", match: /\/reference\// },
    { label: "Rust API", href: "api/teamcraft/index.html", match: /\/api\// },
    { label: "Source", href: "https://github.com/rudalabs/TeamCraft", external: true }
  ];

  // The colours follow the browser (prefers-color-scheme, see doxygen.css);
  // a theme remembered by mdBook's (hidden) theme picker is dropped.
  try { localStorage.removeItem("mdbook-theme"); } catch (e) { /* private mode */ }

  function el(tag, attrs, children) {
    var node = document.createElement(tag);
    Object.keys(attrs || {}).forEach(function (k) { node.setAttribute(k, attrs[k]); });
    (children || []).forEach(function (c) {
      if (c) node.appendChild(typeof c === "string" ? document.createTextNode(c) : c);
    });
    return node;
  }

  // ------------------------------------------------------------ title + tabs
  var path = window.location.pathname;
  var list = el("ul", {}, tabs.map(function (t) {
    var current = !t.external && t.match.test(path);
    var link = el("a", { href: t.external ? t.href : root + t.href }, [t.label]);
    if (t.external) link.setAttribute("rel", "noopener");
    return el("li", current ? { "class": "current" } : {}, [link]);
  }));

  // the sidebar toggle of the hidden mdBook menu bar
  var menu = el("button", { id: "dox-menu-toggle", type: "button", title: "Show or hide the navigation tree", "aria-label": "Navigation tree" }, ["☰"]);
  menu.addEventListener("click", function () {
    var anchor = document.getElementById("mdbook-sidebar-toggle-anchor");
    if (anchor) anchor.click();
  });

  var search = el("div", { id: "dox-search" });
  var top = el("header", { id: "dox-top" }, [
    el("div", { id: "dox-titlearea" }, [
      el("a", { href: root + "index.html" }, [
        el("img", { src: root + "images/teamcraft-icon.svg", alt: "" }),
        el("div", {}, [
          el("div", { id: "dox-projectname" }, ["TeamCraft", el("span", { id: "dox-projectnumber" }, [version])]),
          el("div", { id: "dox-projectbrief" }, ["Open-source product lifecycle management in pure Rust"])
        ])
      ])
    ]),
    el("nav", { id: "dox-tabs", "aria-label": "Sections" }, [menu, list, el("span", { "class": "dox-spacer" }), search])
  ]);
  var container = document.getElementById("mdbook-body-container") || document.body;
  container.insertBefore(top, container.firstChild);

  // ------------------------------------------------------------------ search
  // mdBook's search form moves into the tab bar; its results open below it.
  var form = document.getElementById("mdbook-searchbar-outer");
  var bar = document.getElementById("mdbook-searchbar");
  var wrapper = document.getElementById("mdbook-search-wrapper");
  var toggle = document.getElementById("mdbook-search-toggle");
  if (form && bar && wrapper) {
    search.appendChild(form);
    bar.setAttribute("placeholder", "Search");
    // mdBook (0.5) loads its search index only when its own toggle opens the
    // search (searcher.js showSearch). That toggle sits in the hidden menu
    // bar, so typing into the moved box searched without an index and stayed
    // "searching" for ever. The first focus opens the search through the
    // toggle once, which loads the index; searcher.js then searches for what
    // was typed meanwhile.
    var loadIndex = function () {
      if (!toggle || document.getElementById("mdbook-search-index")) return;
      if (!wrapper.classList.contains("hidden")) return;
      // the toggle's handler also scrolls to the top: keep the reader's place
      var x = window.scrollX, y = window.scrollY;
      toggle.click();
      window.scrollTo(x, y);
    };
    var open = function () { if (bar.value.trim()) wrapper.classList.remove("hidden"); };
    var close = function () { wrapper.classList.add("hidden"); };
    bar.addEventListener("focus", function () {
      loadIndex();
      if (bar.value.trim()) { open(); } else { close(); }
    });
    bar.addEventListener("input", function () { loadIndex(); open(); });
    bar.addEventListener("keydown", function (e) { if (e.key === "Escape") { close(); bar.blur(); } });
    form.addEventListener("submit", function (e) { e.preventDefault(); open(); });
    document.addEventListener("click", function (e) {
      if (!wrapper.contains(e.target) && !search.contains(e.target)) close();
    });
    // a link with ?search=… was already opened by searcher.js (it runs first)
    if (bar.value.trim()) { open(); } else { close(); }
  }

  // ------------------------------------------------- breadcrumb and footer
  var crumbs = [el("a", { href: root + "index.html" }, ["TeamCraft"])];
  var active = document.querySelector("#mdbook-sidebar a.active");
  if (active) {
    var item = active.closest("li");
    var top_item = item;
    while (top_item && top_item.parentElement && top_item.parentElement.closest("li")) {
      top_item = top_item.parentElement.closest("li");
    }
    for (var sib = top_item && top_item.previousElementSibling; sib; sib = sib.previousElementSibling) {
      if (sib.classList.contains("part-title")) {
        crumbs.push(el("span", { "class": "dox-sep" }, ["›"]), el("span", {}, [sib.textContent.trim()]));
        break;
      }
    }
    var title = active.cloneNode(true);
    title.querySelectorAll("strong").forEach(function (s) { s.remove(); });
    if (active.getAttribute("href") && !/index\.html$/.test(active.getAttribute("href"))) {
      crumbs.push(el("span", { "class": "dox-sep" }, ["›"]), el("span", { "class": "dox-crumb" }, [title.textContent.trim()]));
    }
  }
  crumbs.push(el("span", { "class": "dox-generated" }, ["TeamCraft " + version + " · MPL-2.0 · Generated by mdBook"]));
  container.appendChild(el("footer", { id: "dox-navpath" }, crumbs));
})();
